function pad(n){ return String(n).padStart(2,'0'); }
function toDateStr(d){ return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; }
function parseDateLocal(s){ const [y,m,d]=s.split('-').map(Number); return new Date(y,m-1,d); }
function addDays(date, n){ const d=new Date(date); d.setDate(d.getDate()+n); return d; }
function monthDateRange(date){ return [new Date(date.getFullYear(),date.getMonth(),1), new Date(date.getFullYear(),date.getMonth()+1,0)]; }
function weekDateRange(date){ const d=new Date(date); const day=d.getDay(); const monday=addDays(d, day===0 ? -6 : 1-day); return [monday, addDays(monday,6)]; }
function absNorm(x){ return ((x%360)+360)%360; }
function angleDiff(a,b){ let d=Math.abs(absNorm(a)-absNorm(b)); return d>180?360-d:d; }
function signIndex(lon){ return Math.floor(absNorm(lon)/30); }
function degInSign(lon){ return Math.floor(absNorm(lon)%30); }
function formatPos(lon){ return `${SIGNS[signIndex(lon)]}${degInSign(lon)}°`; }
function dateLabel(dateStr){ const d=parseDateLocal(dateStr); return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日（${WEEKDAYS[d.getDay()]}）`; }
function shortDate(dateStr){ const d=parseDateLocal(dateStr); return `${d.getMonth()+1}/${d.getDate()}`; }
function getPlanets(dateStr){ return EPHEMERIS[dateStr] || null; }
function houseOf(lon){ const x=absNorm(lon); for(let i=0;i<12;i++){ const a=HOUSE_CUSPS[i], b=HOUSE_CUSPS[(i+1)%12]; if(a<=b){ if(x>=a && x<b) return `${i+1}H`; } else { if(x>=a || x<b) return `${i+1}H`; } } return '1H'; }
function planetLine(p){ return `${PLANET_META[p].en}:${formatPos(currentPlanets[p])}/${houseOf(currentPlanets[p])}`; }

let currentPlanets = null;

function getPhaseForDate(dateStr){
  const dayStart = `${dateStr}T00:00:00+09:00`;
  const dayEnd = `${dateStr}T23:59:59+09:00`;
  const todays = MOON_PHASES.filter(p => `${p.date}T${p.time}:00+09:00` >= dayStart && `${p.date}T${p.time}:00+09:00` <= dayEnd);
  if(todays.length) return `${todays.map(p=>`${p.name}（${p.date} ${p.time} JST）`).join(' / ')}`;
  const dt = `${dateStr}T12:00:00+09:00`;
  let prev=null;
  for(const p of MOON_PHASES){ if(`${p.date}T${p.time}:00+09:00` <= dt) prev=p; }
  if(!prev) return '月相データ範囲外';
  return `${prev.name}期（${prev.date} ${prev.time} JST）`;
}
function phasesInRange(start,end){
  const s=toDateStr(start), e=toDateStr(end);
  return MOON_PHASES.filter(p=>p.date>=s && p.date<=e).map(p=>`・${p.name}（${p.date} ${p.time} JST）`).join('\n') || '・期間内の朔弦望なし';
}
function ingressesForDate(dateStr){
  return INGRESSES.filter(i=>i.date===dateStr).map(i=>`${i.time} ${i.planetJp}：${SIGNS[i.from]}→${SIGNS[i.to]}`).join('\n') || 'なし';
}
function ingressesInRange(start,end){
  const s=toDateStr(start), e=toDateStr(end);
  return INGRESSES.filter(i=>i.date>=s && i.date<=e).map(i=>`・${i.date} ${i.time} ${i.planetJp}：${SIGNS[i.from]}→${SIGNS[i.to]}`).join('\n') || '・なし';
}

const ASPECTS_GENERAL = [
  {name:'合', sym:'☌', angle:0, orb:5}, {name:'セクスタイル', sym:'⚹', angle:60, orb:3},
  {name:'スクエア', sym:'□', angle:90, orb:4}, {name:'トライン', sym:'△', angle:120, orb:4},
  {name:'オポジション', sym:'☍', angle:180, orb:5}
];
const ASPECTS_PERSONAL = ASPECTS_GENERAL; // 個人鑑定もメジャーアスペクトのみ
function findAspect(a,b, list=ASPECTS_GENERAL, moonBonus=false){
  const d=angleDiff(a,b);
  let best=null;
  for(const asp of list){ const orb=Math.abs(d-asp.angle); const max=asp.orb+(moonBonus?1:0); if(orb<=max && (!best || orb<best.orb)) best={...asp, orb}; }
  return best;
}
function transitAspects(planets, includeMoonOnly=false){
  const keys=Object.keys(PLANET_META);
  const out=[];
  for(let i=0;i<keys.length;i++) for(let j=i+1;j<keys.length;j++){
    const a=keys[i], b=keys[j];
    if(includeMoonOnly && a!=='moon' && b!=='moon') continue;
    const asp=findAspect(planets[a], planets[b], ASPECTS_GENERAL, a==='moon'||b==='moon');
    if(asp) out.push({a,b,...asp});
  }
  return out.sort((x,y)=>x.orb-y.orb);
}
function personalAspects(planets){
  const out=[];
  for(const [tk, tlon] of Object.entries(planets)){
    for(const [nk, n] of Object.entries(NATAL)){
      const asp=findAspect(tlon, n.lon, ASPECTS_PERSONAL, tk==='moon'||nk==='moon');
      if(asp && asp.orb<=3.05) out.push({tk,nk,house:houseOf(tlon),...asp});
    }
  }
  return out.sort((a,b)=>a.orb-b.orb);
}
function aspectText(a){
  const t=PLANET_META[a.a], u=PLANET_META[a.b];
  return `${t.sym}${a.sym}${u.sym}${u.en}(${a.name},orb${a.orb.toFixed(1)}°)`;
}

function isMoonAspect(a){ return a.a==='moon' || a.b==='moon'; }
function isFastTransitKey(k){ return ['moon','mercury','venus','mars','sun'].includes(k); }
function moonAspectScore(a){
  let s = a.orb;
  const other = a.a==='moon' ? a.b : a.a;
  if(['sun','mars','venus','mercury','saturn','pluto'].includes(other)) s -= 0.35;
  if(a.orb<=1.0) s -= 0.6;
  if(a.orb<=2.0) s -= 0.3;
  return s;
}
function dayMoonAspects(ds, max=3, orbMax=2.5){
  return transitAspects(getPlanets(ds), true)
    .filter(a=>a.orb<=orbMax)
    .sort((a,b)=>moonAspectScore(a)-moonAspectScore(b))
    .slice(0,max);
}
function dayNonMoonMajorAspects(ds, max=3, orbMax=2.0){
  return transitAspects(getPlanets(ds), false)
    .filter(a=>!isMoonAspect(a) && a.orb<=orbMax)
    .sort((a,b)=>a.orb-b.orb)
    .slice(0,max);
}
function peakDaysByMoon(dates, count=3){
  return dates.map(ds=>{
    const moon = dayMoonAspects(ds, 4, 2.5);
    const other = dayNonMoonMajorAspects(ds, 2, 1.5);
    const score = moon.reduce((sum,a)=>sum + (2.8 - Math.min(a.orb,2.8)),0) * 2
                + other.reduce((sum,a)=>sum + (1.8 - Math.min(a.orb,1.8)),0);
    return {ds, score, moon, other, tops:[...moon.slice(0,3), ...other.slice(0,2)].slice(0,4)};
  }).sort((a,b)=>b.score-a.score || (a.tops[0]?.orb??9)-(b.tops[0]?.orb??9)).slice(0,count);
}
function formatAspectListWithDate(list){
  return list.map(x=>`${shortDate(x.ds)} ${aspectText(x)}`).join('\n') || '少なめ';
}
function flowFromMoonAspects(list, fallback='月の流れを見ながら、気持ちを整える時間。'){
  const text = list.map(a=>{
    const other = a.a==='moon' ? a.b : a.a;
    if(other==='pluto') return '深い感情や本音が浮かびやすい';
    if(other==='mars') return '行動したい気持ちが強まりやすい';
    if(other==='venus') return '人との距離感や心地よさを見直しやすい';
    if(other==='mercury') return '言葉や考えが動きやすい';
    if(other==='saturn') return '落ち着いて整える力が働きやすい';
    if(other==='sun') return '自分の方向性を意識しやすい';
    if(other==='jupiter') return '気持ちが広がりやすい';
    if(other==='neptune') return '感覚が曖昧になりやすい';
    if(other==='uranus') return '急なひらめきや変化が入りやすい';
    return '気持ちが動きやすい';
  });
  const uniq=[...new Set(text)];
  return uniq.length ? uniq.slice(0,2).join('。') + '。' : fallback;
}

function personalAspectText(a){
  const t=PLANET_META[a.tk]; const n=NATAL[a.nk];
  return `T.${t.en}${a.sym}N.${n.jp}(${a.name},${a.house},orb${a.orb.toFixed(1)}°)`;
}
function formatPlanetPositions(planets, withHouses=false){
  return Object.entries(PLANET_META).map(([k,m])=>`${m.sym}${m.en}:${formatPos(planets[k])}${withHouses?`/${houseOf(planets[k])}`:''}`).join(' / ');
}
function updatePlanetDisplay(){
  const dateStr=document.getElementById('datePicker').value;
  const p=getPlanets(dateStr); currentPlanets=p;
  const el=document.getElementById('planetDisplay');
  if(!p){ el.innerHTML='<div class="panel">データ範囲外です</div>'; return; }
  el.innerHTML = Object.entries(PLANET_META).map(([k,m])=>`<div class="planet-card"><div class="name">${m.jp}</div><div class="sign">${SIGNS[signIndex(p[k])]}</div><div class="deg">${degInSign(p[k])}°</div></div>`).join('');
}

function awaiFromData(dateStr, planets, moonAsps, majorAsps){
  const d=parseDateLocal(dateStr);
  const m=d.getMonth()+1, day=d.getDate();
  const moonSign = SIGNS[signIndex(planets.moon)];
  const all=[...moonAsps, ...majorAsps].sort((a,b)=>a.orb-b.orb);
  const tight=all.filter(a=>a.orb<=2.0);
  const veryTight=all.filter(a=>a.orb<=1.0);
  const isMoon = a => a.a==='moon' || a.b==='moon';
  const has = (a, p) => a.a===p || a.b===p;
  const moonTop = moonAsps.slice().sort((a,b)=>a.orb-b.orb)[0];
  const majorTop = majorAsps.slice().sort((a,b)=>a.orb-b.orb)[0];
  const todaySeed = (m*31 + day) % 7;

  const moonTemplates = {
    '牡羊座': [
      ['動き出す日',['考えすぎる前に','小さく身体を向けてみる…','動いた先で見えてくるものがありそう'],'今日何をひとつ動かす？'],
      ['火を入れる日',['内側にある勢いを','少しだけ外に出してみる','始めるには十分な日'],'今日何を始めたい？']
    ],
    '牡牛座': [
      ['感覚を戻す日',['急がずに','手触りのあるものを選んでみる…','身体が安心する方へ'],'今日何を味わいたい？'],
      ['整えて受け取る日',['好きなものを近くに置くと','気持ちが少し戻ってくる','豊かさは小さなところにあるかも'],'今日何を受け取る？']
    ],
    '双子座': [
      ['言葉が動く日',['ふと浮かんだ言葉が','次の扉を開くかも…','軽く話してみて'],'今日誰に何を伝えたい？'],
      ['風を通す日',['考えを少し外に出すと','流れが変わっていく','軽さを選んでみて'],'今日何をメモする？']
    ],
    '蟹座': [
      ['やさしく戻る日',['外に向けすぎた意識を','少し自分の内側へ…','安心する場所を整えてみる'],'今日どこでほっとする？'],
      ['心を温める日',['大切なものを思い出すと','気持ちの輪郭が戻ってくる','無理に急がなくていい'],'今日何を大事にしたい？']
    ],
    '獅子座': [
      ['光を思い出す日',['小さな表現が','誰かに届くかも…','好きなことに少し光を当てて'],'今日何を表現したい？'],
      ['自分を出す日',['遠慮しすぎていたものを','少しだけ前に出してみる','楽しさが合図になるかも'],'今日何を楽しみたい？']
    ],
    '乙女座': [
      ['小さく整える日',['気になっていたことを','ひとつだけ整えると','心の余白が戻ってくる…'],'今日何を整える？'],
      ['手を入れる日',['細かなことに目が向く日','完璧じゃなくていいから','少しだけ手直ししてみて'],'今日どこを整えたい？']
    ],
    '天秤座': [
      ['結び直す日',['距離感を少し変えると','関係の風通しがよくなるかも…','心地よい方へ整えてみて'],'今日誰と心地よくいたい？'],
      ['風通しを作る日',['合わせすぎず','離れすぎず…','ちょうどいい場所を探してみる'],'今日どんな距離感が楽？']
    ],
    '蠍座': [
      ['深く感じる日',['言葉にしきれないものが','内側で静かに動いている…','急がず感じてみて'],'今日何を感じてる？'],
      ['本音に触れる日',['表面じゃなくて','奥にあるものが動いてる感じ…','深いところで何かが整っていく'],'今日何が見えてきた？']
    ],
    '射手座': [
      ['視界を広げる日',['少し遠くを見ると','今の悩みが小さく見えるかも…','風に乗る準備をしてみて'],'今日どこへ意識を向ける？'],
      ['遠くを見る日',['答えを急がず','広い方から眺めてみる','新しい道が見えるかも'],'今日何を学びたい？']
    ],
    '山羊座': [
      ['形にする日',['思いを現実に置いてみる','小さな一歩でいい…','積み重ねが味方になる'],'今日何を形にする？'],
      ['足場を作る日',['やることを少し絞ると','進む道が見えやすくなる','静かに整えてみて'],'今日何を終わらせたい？']
    ],
    '水瓶座': [
      ['風を変える日',['いつもの見方を少し外すと','新しい答えが入ってくるかも…','自由な方へ開いてみて'],'今日何を変えてみる？'],
      ['未来を見る日',['少し先の自分から','今を眺めてみる…','選び直せるものがありそう'],'今日どんな未来を選ぶ？']
    ],
    '魚座': [
      ['ほどける日',['境界がやわらかくなって','気持ちが流れやすい日…','無理にまとめなくていい'],'今日何をゆるめる？'],
      ['夢を拾う日',['ぼんやり浮かぶものの中に','小さなヒントがありそう','静かな時間を少しだけ'],'今日何を感じたい？']
    ]
  };

  let tpl = (moonTemplates[moonSign] || [['流れを感じる日',['小さな違和感が','次の扉を教えてくれるかも…'],'今日何を整えたい？']])[todaySeed % (moonTemplates[moonSign] || []).length || 0];
  let [title, lines, q] = tpl;

  // 月のタイトアスペクトは、その日の体感として最優先。これで毎日同じ冥王星文になりにくくする。
  if(moonTop && moonTop.orb<=2.2){
    if(has(moonTop,'pluto')) [title, lines, q] = ['本音に触れる日',['奥にしまっていたものが','静かに顔を出すかも…','深いところで何かが動いている'],'今日何が見えてきた？'];
    else if(has(moonTop,'uranus')) [title, lines, q] = ['風が変わる日',['予定通りじゃない流れに','新しいヒントが混ざっているかも…','軽く向きを変えてみて'],'今日何を変えてみる？'];
    else if(has(moonTop,'mars')) [title, lines, q] = ['熱が動く日',['気持ちが少し前のめりになりそう','焦らず小さく動かして…','身体の声も聞いてみる'],'今日何をひとつ動かす？'];
    else if(has(moonTop,'venus')) [title, lines, q] = ['心地よさを選ぶ日',['好きなものに触れると','気持ちがやわらかく戻るかも…','無理なく整えて'],'今日何を心地よくしたい？'];
    else if(has(moonTop,'saturn')) [title, lines, q] = ['静かに整える日',['気持ちを落ち着けて','必要なものだけ残していく…','急がなくていい'],'今日何を整える？'];
    else if(has(moonTop,'jupiter')) [title, lines, q] = ['広がりを受け取る日',['小さな安心が','次の広がりにつながるかも…','ゆるやかに開いてみて'],'今日何を広げたい？'];
    else if(has(moonTop,'neptune')) [title, lines, q] = ['夢をほどく日',['曖昧な気持ちの中に','大事なサインが混ざっていそう…','静かに感じてみて'],'今日何をゆるめたい？'];
    else if(has(moonTop,'mercury')) [title, lines, q] = ['言葉を拾う日',['ふと出てきた言葉を','流さずに残してみる…','そこに今のヒントがあるかも'],'今日何を書いておく？'];
    else if(has(moonTop,'sun')) [title, lines, q] = ['自分に戻る日',['今の気持ちと方向性が','少しずつ噛み合っていく…','素直な方を選んでみて'],'今日何を大切にしたい？'];
  } else if(majorTop && majorTop.orb<=1.2){
    // 月が強くない日は、最タイトな主要アスペクトで空気を変える。
    if(has(majorTop,'uranus')) [title, lines, q] = ['風が変わる日',['急に流れが動いたり','ひらめきが降りてきたり…','いつもの外側を見てみて'],'今日何を変えてみる？'];
    else if(has(majorTop,'mercury')) [title, lines, q] = ['言葉がひらく日',['言葉にすると','思っていたより軽くなるかも…','小さく伝えてみて'],'今日何を伝えたい？'];
    else if(has(majorTop,'venus')) [title, lines, q] = ['好きに戻る日',['心地よさを選ぶことで','流れが整っていく…','好きなものを近くに置いて'],'今日何を受け取りたい？'];
    else if(has(majorTop,'mars')) [title, lines, q] = ['一歩動かす日',['止まっていたものに','少し火が入る感じ…','小さく始めてみて'],'今日何を一つ動かす？'];
    else if(has(majorTop,'pluto') && todaySeed%2===0) [title, lines, q] = ['本質に触れる日',['表面じゃなくて','奥にあるものが動いてる感じ…','深いところで何かが整っていく'],'今日何が見えてきた？'];
  }

  // かも過多を避けるため、文章は基本2〜3行＋問い1つ。
  return `今日のあわい言葉 ${m}/${day}\n\n${title}\n\n${lines.join('\n\n')}\n\n${q}\n\n素敵な1日を🍃`;
}
function aspectMeaning(a){
  const pair=[a.a,a.b];
  const hard = a.name==='スクエア' || a.name==='オポジション';
  if(pair.includes('pluto')) return hard ? '本音や深い欲求が強く揺さぶられる' : '深いところにある本質が浮かび上がる';
  if(pair.includes('uranus')) return '流れが急に切り替わり、ひらめきや変化が入りやすい';
  if(pair.includes('neptune')) return hard ? '境界が曖昧になりやすく、理想と現実の差を感じやすい' : '直感やイメージが広がりやすい';
  if(pair.includes('saturn')) return hard ? 'やるべきことや責任を意識しやすい' : '落ち着いて整える力が使いやすい';
  if(pair.includes('jupiter')) return '広げる力が働き、学びや発信を大きくしやすい';
  if(pair.includes('mars')) return hard ? '勢いが強まり、焦りや衝突に注意したい' : '行動へ移しやすい';
  if(pair.includes('venus')) return '人間関係や楽しみ、心地よさを整えやすい';
  if(pair.includes('mercury')) return '言葉・思考・連絡が動きやすい';
  return '流れを整えやすい';
}
function energySummary(planets, moonAsps, majorAsps){
  const top=[...moonAsps, ...majorAsps].sort((a,b)=>a.orb-b.orb).slice(0,4);
  const moonSign=SIGNS[signIndex(planets.moon)];
  const details=top.map(aspectMeaning).filter((v,i,a)=>a.indexOf(v)===i).slice(0,2);
  return `${moonSign}の月が軸。${details.join('。') || '内側のリズムを整えやすい'}日。`;
}
function todayActions(planets, moonAsps, majorAsps){
  const all=[...moonAsps,...majorAsps];
  const actions=[];
  if(all.some(a=>a.a==='mercury'||a.b==='mercury')) actions.push('言葉にしたいことを短くメモする');
  if(all.some(a=>a.a==='venus'||a.b==='venus')) actions.push('人との距離感や心地よさを整える');
  if(all.some(a=>a.a==='mars'||a.b==='mars')) actions.push('小さく一つだけ行動に移す');
  if(all.some(a=>a.a==='pluto'||a.b==='pluto')) actions.push('本音や違和感を見ないふりしない');
  if(actions.length<2) actions.push('予定を詰めすぎず余白を残す');
  return actions.slice(0,3);
}
function todayCaution(moonAsps, majorAsps){
  const hard=[...moonAsps,...majorAsps].filter(a=>a.name==='スクエア'||a.name==='オポジション').sort((a,b)=>a.orb-b.orb)[0];
  if(!hard) return '流れがよくても、急ぎすぎず丁寧に進める。';
  if(hard.a==='mars'||hard.b==='mars') return '勢いが強く出やすいので、衝動的な反応は一度置く。';
  if(hard.a==='neptune'||hard.b==='neptune') return '曖昧なまま決めず、違和感があれば一度確認する。';
  if(hard.a==='venus'||hard.b==='venus') return '相手に合わせすぎず、自分の心地よさも大切にする。';
  return '強く動く感情を、すぐ結論にしない。';
}
function buildAwai(dateStr){
  const p=getPlanets(dateStr); const moonAsps=transitAspects(p,true); const majorAsps=transitAspects(p,false).filter(a=>a.a!=='moon'&&a.b!=='moon');
  currentAwaiText=awaiFromData(dateStr,p,moonAsps,majorAsps);
  const actions=todayActions(p,moonAsps,majorAsps);
  return `【${dateLabel(dateStr)}】月相：${getPhaseForDate(dateStr)}\n\n◆天体位置\n${formatPlanetPositions(p)}\n\n◆イングレス\n${ingressesForDate(dateStr)}\n\n◆月のアスペクト（トランジット同士）\n${moonAsps.slice(0,8).map(aspectText).join('\n') || 'なし'}\n\n◆天体間アスペクト\n${majorAsps.slice(0,10).map(aspectText).join('\n') || 'なし'}\n\n◆今日の星読み\n**今日のエネルギーの特徴**\n${energySummary(p,moonAsps,majorAsps)}\n\n**おすすめの行動**\n- ${actions.join('\n- ')}\n\n**注意点**\n${todayCaution(moonAsps,majorAsps)}\n\n◆あわい言葉\n${currentAwaiText}`;
}
function planetTheme(k){
  return {sun:'方向性・自己表現', moon:'感情・身体感覚', mercury:'言葉・思考・発信', venus:'関係性・楽しみ・受け取り', mars:'行動・衝動・体力', jupiter:'拡大・学び・発信', saturn:'責任・制限・整える力', uranus:'変化・独自性・突破', neptune:'直感・境界・夢', pluto:'本質・変容・深い力'}[k] || 'テーマ';
}
function houseTheme(h){
  return {'1H':'自己像・見せ方','2H':'価値・お金・感覚','3H':'言葉・学び・発信','4H':'土台・家・安心','5H':'創造性・楽しみ・自己表現','6H':'日課・身体・整えること','7H':'対話・関係性','8H':'深い結びつき・変容','9H':'学び・旅・視野','10H':'社会的立場・肩書き・発信','11H':'仲間・未来・コミュニティ','12H':'休息・内省・無意識'}[h] || h;
}
function selectPersonalFocus(asps){
  // 今日読むものは最大5つ。まずorb0〜2°、次に日々変化する速い天体を優先。
  const fastKeys=['moon','mercury','venus','mars','sun'];
  const score = a => {
    let v = a.orb;
    if(fastKeys.includes(a.tk)) v -= 1.6;
    if(a.tk==='moon') v -= 0.8;
    if(a.orb<=1.0) v -= 1.0;
    if(a.orb<=2.0) v -= 0.5;
    // 遅い天体同士/長期背景は下げすぎず、ただし毎日同じになりすぎないよう少し後ろへ
    if(['pluto','neptune','uranus','saturn','jupiter'].includes(a.tk)) v += 0.35;
    return v;
  };
  const tight = asps.filter(a=>a.orb<=3.05).sort((a,b)=>score(a)-score(b));
  const selected=[];
  for(const a of tight){
    const exists = selected.some(x=>x.tk===a.tk && x.nk===a.nk && x.sym===a.sym);
    if(!exists) selected.push(a);
    if(selected.length>=5) break;
  }
  return selected;
}
function personalAspectMeaning(a){
  const t=PLANET_META[a.tk].jp, n=NATAL[a.nk].jp, h=a.house;
  const base=`${t}がN.${n}に${a.name}（${h}：${houseTheme(h)}）`;
  const hard=a.name==='スクエア'||a.name==='オポジション';
  const theme=planetTheme(a.tk);
  let msg='';
  if(a.tk==='moon') msg= hard ? '感情が揺れやすいので、反応を急がないことが大切。' : '感情の流れが自然に動き、気づきが出やすい。';
  else if(a.tk==='mercury') msg= hard ? '言葉や考えが強く動くぶん、言い切りすぎに注意。' : '言葉・発信・学びを形にしやすい。';
  else if(a.tk==='venus') msg= hard ? '関係性や心地よさに違和感が出やすい。' : '人とのやりとりや楽しみを受け取りやすい。';
  else if(a.tk==='mars') msg= hard ? '行動力が強いぶん、焦りや衝突に注意。' : '小さく動かす力が出やすい。';
  else if(a.tk==='sun') msg= hard ? '方向性を問い直す力が働く。' : '自分の方向性を外へ出しやすい。';
  else if(a.tk==='pluto') msg='深い変容の背景。社会的な見せ方や本音に触れやすい。';
  else if(a.tk==='saturn') msg='責任・制限・整え直しの背景。無理を減らすことが大切。';
  else if(a.tk==='uranus') msg='変化や突破の背景。いつもの見せ方を更新しやすい。';
  else if(a.tk==='neptune') msg='境界や直感の背景。休息と内省が必要。';
  else msg=`${theme}が動く。`;
  return `${base}。${msg}`;
}
function personalAdvice(dateStr){
  const p=getPlanets(dateStr);
  const asps=personalAspects(p);
  const focus=selectPersonalFocus(asps);
  const twelfth=Object.keys(p).filter(k=>houseOf(p[k])==='12H').map(k=>PLANET_META[k].jp);
  const moonHouse=houseOf(p.moon);
  const shownAsps = asps.slice(0,12);
  const focusLines=focus.map(personalAspectMeaning);
  let feature = focusLines.length
    ? focusLines.join('\n')
    : '今日はタイトな個人アスペクトが少なめ。月のサインとハウスを中心に、身体感覚を整えたい日。';
  feature += `\n月は${moonHouse}（${houseTheme(moonHouse)}）にあり、今日の感情の入口になります。`;
  if(twelfth.length>=2) feature += `\n${twelfth.join('・')}が12Hにあり、休息と内省も大切です。`;

  const actions=[];
  if(focus.some(a=>a.tk==='moon')) actions.push('今日湧いた感情や身体感覚を短くメモする');
  if(focus.some(a=>a.tk==='mercury')) actions.push('言葉・発信・学びを一つ形にする');
  if(focus.some(a=>a.tk==='venus')) actions.push('関係性や心地よさを見直す');
  if(focus.some(a=>a.tk==='mars')) actions.push('小さく動かし、無理な突破は避ける');
  if(moonHouse==='10H'||focus.some(a=>a.house==='10H')) actions.push('発信・肩書き・見せ方を少し整える');
  if(moonHouse==='12H'||twelfth.length>=2) actions.push('予定を詰めすぎず、余白を残す');
  if(actions.length<3) actions.push('感じたことを短くメモする','今日の違和感を一つ言葉にする');
  const caution = focus.some(a=>a.tk==='moon' && (a.name==='スクエア'||a.name==='オポジション'))
    ? '月のハードアスペクトがあるため、感情の反応をすぐ結論にしない。'
    : (moonHouse==='12H'||twelfth.length>=2)
      ? '12ハウスが強く、気づかないうちに消耗しやすい配置。早めに休む。'
      : (focus.some(a=>a.name==='スクエア'||a.name==='オポジション') ? 'タイトなハードアスペクトがあるため、反応で動かず一呼吸置く。' : '流れがよくても、詰め込みすぎない。');
  return `## ${dateLabel(dateStr)} 個人鑑定\n\n◆トランジット天体\n${formatPlanetPositions(p,true)}\n\n◆ネイタルとのアスペクト（メジャーのみ・orb0〜3°優先 / 上位12件）\n${shownAsps.map(personalAspectText).join('\n') || '該当なし'}${asps.length>12?`\n…他${asps.length-12}件`:''}\n\n◆今日読む主なアスペクト（最大5つ・orb0〜2°と速い天体優先）\n${focus.map(personalAspectText).join('\n') || '該当なし'}\n\n**今日のエネルギーの特徴**\n${feature}\n\n**おすすめの行動**\n- ${actions.slice(0,3).join('\n- ')}\n\n**注意点**\n${caution}\n\n**ひとことメッセージ**\n今日強く触れている配置を、無理に結論にせず、小さな選択に映してみて。`;
}
function buildPersonal(dateStr){ return personalAdvice(dateStr); }

function rangeDates(start,end){ const arr=[]; for(let d=new Date(start); d<=end; d=addDays(d,1)) arr.push(toDateStr(d)); return arr; }
function weekNumber(d){ const start=new Date(d.getFullYear(),0,1); return Math.ceil((((d-start)/86400000)+start.getDay()+1)/7); }
function buildWeek(dateStr){
  const [s,e]=weekDateRange(parseDateLocal(dateStr));
  const dates=rangeDates(s,e);
  const peak=peakDaysByMoon(dates,3);
  const firstHalfMoon=dates.slice(0,3).flatMap(ds=>dayMoonAspects(ds,3,2.5).map(a=>({...a,ds}))).slice(0,7);
  const secondHalfMoon=dates.slice(3).flatMap(ds=>dayMoonAspects(ds,3,2.5).map(a=>({...a,ds}))).slice(0,8);
  const firstHalfOther=dates.slice(0,3).flatMap(ds=>dayNonMoonMajorAspects(ds,2,1.5).map(a=>({...a,ds}))).slice(0,4);
  const secondHalfOther=dates.slice(3).flatMap(ds=>dayNonMoonMajorAspects(ds,2,1.5).map(a=>({...a,ds}))).slice(0,4);
  const moonFlowFirst=flowFromMoonAspects(firstHalfMoon);
  const moonFlowSecond=flowFromMoonAspects(secondHalfMoon);
  const allMoon=firstHalfMoon.concat(secondHalfMoon);
  const weekTheme = allMoon.some(a=>(a.a==='moon'?a.b:a.a)==='pluto') ? '気持ちの奥にある本音を拾いながら、整えていく週。'
    : allMoon.some(a=>(a.a==='moon'?a.b:a.a)==='mars') ? '動きたい気持ちと余白のバランスを整える週。'
    : '月の流れを感じながら、気持ちと言葉を整える週。';
  return `## 今週の星読み\n\n【今週：${dateLabel(toDateStr(s))}〜${dateLabel(toDateStr(e))}】\n\n◆今週の月相（朔弦望）\n${phasesInRange(s,e)}\n\n◆今週のイングレス\n${ingressesInRange(s,e)}\n\n◆あわいの週言葉\nWeek ${weekNumber(s)}\n${weeklyPhrase(dates)}\n\n◆ピーク日と主な月アスペクト\n${peak.map(x=>`・${shortDate(x.ds)}：${x.tops.map(aspectText).join(' / ') || '月のタイトアスペクト少なめ'}`).join('\n')}\n\n◆前半（月〜水）の月アスペクト抜粋\n${formatAspectListWithDate(firstHalfMoon)}\n\n◆前半（月〜水）の天体間アスペクト補足\n${formatAspectListWithDate(firstHalfOther)}\n\n◆後半（木〜日）の月アスペクト抜粋\n${formatAspectListWithDate(secondHalfMoon)}\n\n◆後半（木〜日）の天体間アスペクト補足\n${formatAspectListWithDate(secondHalfOther)}\n\n【今週のテーマ】\n${weekTheme}\n\n【前半（月〜水）】\n${moonFlowFirst}\n\n【後半（木〜日）】\n${moonFlowSecond}\n\n【今週のおすすめアクション】\n・気持ちを言葉にする\n・予定を詰めすぎず整える\n・本当に残したいものを選ぶ\n\n【注意ポイント】\n外側の出来事だけで判断せず、月の動きに合わせて感情の変化も見て。`;
}
function weeklyPhrase(dates){
  const first=getPlanets(dates[0]), last=getPlanets(dates[dates.length-1]);
  const hasPluto=dates.some(ds=>transitAspects(getPlanets(ds),false).some(a=>(a.a==='pluto'||a.b==='pluto')&&a.orb<2));
  if(hasPluto) return '感じて、整えて、本物だけ残す週';
  if(signIndex(first.moon)!==signIndex(last.moon)) return '受け取り、動かし、風に乗る週';
  return '整えて、選んで、一歩進む週';
}
function buildMonth(dateStr){
  const [s,e]=monthDateRange(parseDateLocal(dateStr));
  const dates=rangeDates(s,e);
  const peak=peakDaysByMoon(dates,5);
  const firstHalfMoon=dates.slice(0,15).flatMap(ds=>dayMoonAspects(ds,2,2.0).map(a=>({...a,ds}))).slice(0,12);
  const secondHalfMoon=dates.slice(15).flatMap(ds=>dayMoonAspects(ds,2,2.0).map(a=>({...a,ds}))).slice(0,12);
  const firstHalfOther=dates.slice(0,15).flatMap(ds=>dayNonMoonMajorAspects(ds,1,1.3).map(a=>({...a,ds}))).slice(0,8);
  const secondHalfOther=dates.slice(15).flatMap(ds=>dayNonMoonMajorAspects(ds,1,1.3).map(a=>({...a,ds}))).slice(0,8);
  const moonFlowFirst=flowFromMoonAspects(firstHalfMoon, '前半は月の流れを追いながら、内側の反応を整える時間。');
  const moonFlowSecond=flowFromMoonAspects(secondHalfMoon, '後半は月の流れを追いながら、見えてきたことを行動へ移す時間。');
  return `## ${s.getFullYear()}年${s.getMonth()+1}月の星読み\n\n◆今月の月相（朔弦望）\n${phasesInRange(s,e)}\n\n◆今月のイングレス\n${ingressesInRange(s,e)}\n\n◆ピーク日と主な月アスペクト\n${peak.map(x=>`・${shortDate(x.ds)}：${x.tops.map(aspectText).join(' / ') || '月のタイトアスペクト少なめ'}`).join('\n')}\n\n◆前半の月アスペクト抜粋\n${formatAspectListWithDate(firstHalfMoon)}\n\n◆前半の天体間アスペクト補足\n${formatAspectListWithDate(firstHalfOther)}\n\n◆後半の月アスペクト抜粋\n${formatAspectListWithDate(secondHalfMoon)}\n\n◆後半の天体間アスペクト補足\n${formatAspectListWithDate(secondHalfOther)}\n\n【今月のテーマ】\n月の動きから、気持ちの波・関係性・行動のタイミングを整える月。\n\n【前半】\n${moonFlowFirst}\n\n【後半】\n${moonFlowSecond}\n\n【注意点】\nピーク日は月のタイトアスペクトで気持ちが動きやすいので、勢いだけで決めず一呼吸置いて。\n\n【今月のメッセージ】\n月のリズムを味方にすると、必要な選択が見えやすくなる。`;
}

function buildMonthPersonal(dateStr){
  const [s,e]=monthDateRange(parseDateLocal(dateStr)); const dates=rangeDates(s,e);
  let all=[]; dates.forEach(ds=> personalAspects(getPlanets(ds)).forEach(a=>all.push({...a,ds})) );
  const key = a=>`${a.tk}-${a.sym}-${a.nk}`;
  const groups={}; all.forEach(a=>{ const k=key(a); (groups[k]||(groups[k]=[])).push(a); });
  const recurring=Object.values(groups).filter(g=>g.length>=3).sort((a,b)=>Math.min(...a.map(x=>x.orb))-Math.min(...b.map(x=>x.orb))).slice(0,10);
  const lines=recurring.map(g=>{ const best=g.reduce((m,x)=>x.orb<m.orb?x:m,g[0]); return `${personalAspectText(best)}（${shortDate(g[0].ds)}〜${shortDate(g[g.length-1].ds)}、最タイト${shortDate(best.ds)}）`; });
  return `## ${s.getFullYear()}年${s.getMonth()+1}月 個人鑑定\n\n◆今月の月相（朔弦望）\n${phasesInRange(s,e)}\n\n◆月全体で繰り返し出る外天体×ネイタルアスペクト\n${lines.join('\n') || '該当なし'}\n\n**今月のテーマ**\n社会的な見せ方・発信・内側の整え直しが重なる月。\n\n**強い影響が出る時期**\n上記の最タイト日と月相の前後。\n\n**意識すると良いこと**\n- 発信や肩書きの見直し\n- 感情の記録\n- 休息と行動のバランス\n\n**注意点**\n長期トランジットを焦って結論にしないこと。\n\n**メッセージ**\n変化は急がなくて大丈夫。深いところで選び直しが始まっている。`;
}

function generate(mode){
  currentMode=mode;
  const dateStr=document.getElementById('datePicker').value;
  if(!getPlanets(dateStr)){ alert('2026年4月〜12月の日付を選んでください'); return; }
  let title='', text='';
  if(mode===1){ title='今日（あわい言葉）'; text=buildAwai(dateStr); }
  if(mode===2){ title='今日（個人）'; text=buildPersonal(dateStr); }
  if(mode===3){ title='今週（一般）'; text=buildWeek(dateStr); }
  if(mode===4){ title='今月（一般）'; text=buildMonth(dateStr); }
  if(mode===5){ title='今月（個人）'; text=buildMonthPersonal(dateStr); }
  document.getElementById('outputTitle').textContent=title;
  document.getElementById('outputText').textContent=text;
  document.getElementById('outputSection').style.display='block';
  document.getElementById('copyMsg').style.display='none';
}
function copyOutput(){
  const text=document.getElementById('outputText').textContent;
  let copy=text;
  if(currentMode===1){ const marker='◆あわい言葉'; const idx=text.indexOf(marker); copy=idx>=0?text.slice(idx+marker.length).trim():currentAwaiText; }
  navigator.clipboard.writeText(copy).then(()=>{ const msg=document.getElementById('copyMsg'); msg.style.display='block'; setTimeout(()=>msg.style.display='none',1600); });
}

function init(){
  const picker=document.getElementById('datePicker');
  const today=new Date();
  let ds=toDateStr(today);
  if(ds<'2026-04-01' || ds>'2026-12-31') ds='2026-05-27';
  picker.value=ds;
  picker.addEventListener('change',()=>{ updatePlanetDisplay(); document.getElementById('outputSection').style.display='none'; });
  updatePlanetDisplay();
}
document.addEventListener('DOMContentLoaded', init);
